import java.util.Scanner;

public class Main {
    static final int MAXN = 1000111;
    static final long MOD = 1000000007;

    static long fastExp(long base, int exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();

        if (k == 0) {
            System.out.println(fastExp(p, p - 1));
            sc.close();
            return;
        }
        if (k == 1) {
            System.out.println(fastExp(p, p));
            sc.close();
            return;
        }

        long[] visited = new long[p];
        long[] freq = new long[p];

        for (int i = 0; i < p; i++) {
            visited[i] = 0;
            freq[i] = 0;
        }

        for (int start = 1; start < p; start++) {
            if (visited[start] != 0) continue;
            long current = start;
            long countCycle = 0;
            while (visited[(int) current] == 0) {
                visited[(int) current] = 1;
                current = (current * k) % p;
                countCycle++;
            }
            freq[(int) countCycle]++;
        }

        long result = 1;
        for (int length = 1; length <= p - 1; length++) {
            if (freq[length] == 0) continue;
            long tmp = fastExp((length * freq[length] + 1) % MOD, (int) freq[length]);
            result = (result * tmp) % MOD;
        }

        System.out.println(result);
        sc.close();
    }
}
